using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: HasData() no longer uses DateTime.UtcNow
        // (non-deterministic seed data causes spurious migrations).
        // Use a fixed value instead.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// --- Cosmos DB context demonstrating EF Core 9 breaking-change fixes ---

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
        => options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=PLACEHOLDER",
            "ShopDb");

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(b =>
        {
            b.ToContainer("Products");
            b.HasPartitionKey(p => p.Category);

            // EF Core 9 breaking change #1: Discriminator property renamed to "$type".
            // For existing documents that already store "Discriminator", explicitly
            // configure the old property name to avoid data mismatch.
            b.HasDiscriminator<string>("Discriminator");
        });
    }
}

class Product
{
    public string Id { get; set; } = null!;
    public string Name { get; set; } = null!;
    public string Category { get; set; } = null!;
}

// EF Core 9 breaking change #2: Synchronous I/O on Cosmos DB now throws by default.
// All Cosmos queries/saves must use async methods (ToListAsync, SaveChangesAsync, etc.).
class ProductService
{
    private readonly CosmosDbContext _db;
    public ProductService(CosmosDbContext db) => _db = db;

    // WRONG (throws in EF Core 9):
    //   var products = _db.Products.ToList();
    //   _db.SaveChanges();

    // CORRECT — use async:
    public async Task<List<Product>> GetProductsAsync()
        => await _db.Products.ToListAsync();

    public async Task SaveAsync()
        => await _db.SaveChangesAsync();
}

